import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Session store - in-memory for simplicity
const sessions = new Map();

// Middleware: extract session
function authMiddleware(req, res, next) {
  const sid = req.cookies?.sid || req.headers['x-session-id'];
  if (!sid || !sessions.has(sid)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = sessions.get(sid);
  next();
}

// User profile update - supports partial updates via PATCH
app.patch('/api/users/:userId/profile', authMiddleware, async (req, res) => {
  const { userId } = req.params;
  const updates = req.body;

  // Authorization check: users can only update their own profile
  if (req.user.id !== parseInt(userId)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Build dynamic update query from provided fields
  const allowedFields = ['display_name', 'bio', 'avatar_url', 'preferences'];
  const setClauses = [];
  const values = [];
  let paramIndex = 1;

  for (const [key, value] of Object.entries(updates)) {
    if (allowedFields.includes(key)) {
      setClauses.push(`${key} = $${paramIndex}`);
      values.push(value);
      paramIndex++;
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'No valid fields to update' });
  }

  values.push(userId);
  const query = `UPDATE user_profiles SET ${setClauses.join(', ')} WHERE user_id = $${paramIndex}`;

  await pool.query(query, values);
  res.json({ success: true });
});

