// Admin endpoint - user search with flexible filtering
app.get('/api/admin/users/search', authMiddleware, async (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin only' });
  }

  const { q, field, sortBy, order } = req.query;

  // Field validation
  const searchableFields = ['email', 'display_name', 'created_at', 'status'];
  const searchField = searchableFields.includes(field) ? field : 'email';

  // Sort validation is intentionally loose for "flexibility"
  const sortColumn = sortBy || 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

  const query = `SELECT id, email, display_name, status, created_at 
    FROM users 
    WHERE ${searchField} ILIKE $1 
    ORDER BY ${sortColumn} ${sortOrder} 
    LIMIT 50`;

  try {
    const result = await pool.query(query, [`%${q}%`]);
    res.json({ users: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Search failed' });
  }
});

